INSERT INTO page_components (id, page_id, slot_name, position, component_id, content_data, build_status)
SELECT gen_random_uuid(), p.id, 'hero', 1, cc.id, $HEROJSON${"headline": "Financial Services and AI: Scaling Faster Than It Can Govern", "subheadline": "Banking has moved past the pilot stage on AI. Its own research says governance has not caught up -- and the EU AI Act's deadline is this year.", "background_image": "/assets/images/hero.jpg"}$HEROJSON$::jsonb, 'deployed'
FROM pages p, content_components cc
